/* Patient 360: complete, session-only demonstration. No external messages or real accounts. */
const journey = {lead:{name:'Sofía Restrepo',phone:'300 000 0190',source:'Instagram',campaign:'Sonrisa consciente',patient:null},conversation:'lead',patient:9,tooth:11,surface:'Oclusal / incisal',user:'reception',tab:'inbox',messages:[{id:1,thread:'lead',direction:'in',text:'Hola, vi su campaña de valoración de sonrisa. ¿Qué profesional me atendería?',status:'Recibido · demo'}],requests:[],chat:[{id:1,patient:9,author:'Laura · Recepción',text:'Carlos tiene pendiente confirmar su control. Revisar su llegada antes de iniciar atención.'}],findings:[],media:[],automationLog:[],integrations:{domain:'',hosting:'Servicios administrados',channel:'Meta Cloud API'},selectedTemplate:1};
const demoUsers=[{id:'reception',name:'Laura Martínez',role:'Recepción',space:'business'},{id:'dentist',name:'Dra. Daniela Tejada',role:'Profesional',space:'clinic'},{id:'assistant',name:'Sofía Herrera',role:'Auxiliar',space:'clinic'},{id:'admin',name:'Diana Pérez',role:'Administrador',space:'business'},{id:'accountant',name:'Juan Vélez',role:'Contabilidad',space:'business'},{id:'marketing',name:'Andrés Salazar',role:'Comercial',space:'business'}].map(u=>({...u,active:true}));
const services=[{id:1,name:'Valoración integral',price:180000,duration:45,buffer:15,professional:professionals[0],sessions:1},{id:2,name:'Control de ortodoncia',price:120000,duration:30,buffer:15,professional:professionals[1],sessions:1},{id:3,name:'Limpieza preventiva',price:220000,duration:60,buffer:15,professional:professionals[2],sessions:1},{id:4,name:'Diseño de sonrisa · valoración',price:250000,duration:60,buffer:15,professional:professionals[0],sessions:1}];
const templates=[{id:1,name:'Confirmación de cita',event:'Reserva',enabled:true,status:'Aprobada · simulación',text:'Hola {{nombre}}, tu cita será el {{fecha}} a las {{hora}} en {{sede}}. Te atenderá {{profesional}}. Confirma o solicita un cambio.'},{id:2,name:'Recordatorio previo',event:'24 horas antes',enabled:true,status:'Aprobada · simulación',text:'Hola {{nombre}}, te recordamos tu cita del {{fecha}} a las {{hora}} con {{profesional}} en {{sede}}.'},{id:3,name:'Acompañamiento posterior',event:'Salida completada',enabled:true,status:'Aprobada · simulación',text:'Hola {{nombre}}, gracias por visitarnos. ¿Necesitas que nuestro equipo se comunique contigo? Responde a este mensaje y te acompañaremos.'}];
const userNow=()=>demoUsers.find(u=>u.id===journey.user);
const canClinical=()=>userNow().role==='Profesional';
const canFinance=()=>['Administrador','Contabilidad'].includes(userNow().role);
const canBook=()=>['Administrador','Recepción','Profesional'].includes(userNow().role);
const nextId=list=>Math.max(0,...list.map(x=>x.id))+1;
const jButton=(text,action,value='',cls='')=>`<button type="button" class="btn ${cls}" data-j="${action}" data-value="${esc(value)}">${text}</button>`;
const jOptions=(arr,value)=>arr.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('');
const jPatient=()=>patient(journey.lead.patient);
const jAppointment=()=>appointments.filter(a=>a.patient===journey.lead.patient&&a.status!=='Cancelada').sort((a,b)=>b.id-a.id)[0];
const jNote=()=>clinical.find(c=>c.patient===journey.lead.patient&&c.visit===jAppointment()?.id);
const jBill=()=>invoices.find(i=>i.visit===jAppointment()?.id);
const jThread=id=>id===journey.lead.patient?'lead':String(id);
const jDate=()=>state.agendaDay||'2026-10-05';
function jNotice(){return `<div class="j-demo">DEMO · Datos ficticios y cambios durante esta sesión. WhatsApp, cuentas y conexiones se simulan. Recargar reinicia la prueba.</div>`}
function jShell(title,subtitle,body,actions=''){return `<div class="j-scope">${head('PATIENT 360 · FLUJO CONECTADO',title,subtitle,actions)}${jNotice()}${body}</div>`}
function jModal(title,body,kind=null,submit='Guardar'){state.modal={type:'journey',kind};$('#modalRoot').innerHTML=`<div class="modal-back" id="modalBack"><${kind?'form':'section'} ${kind?'id="journeyForm"':''} class="modal j-modal"><div class="j-modal-head"><h2>${title}</h2>${jButton('Cerrar','close')}</div>${body}<p id="jError" class="form-error" role="alert"></p>${kind?`<div class="modal-actions"><button class="btn primary" type="submit">${submit}</button></div>`:''}</${kind?'form':'section'}></div>`;$('#modalRoot input, #modalRoot textarea')?.focus()}
function jFail(text){const e=$('#jError')||$('#formError');if(e)e.textContent=text;else toast(text)}
function jSwitch(id){const u=demoUsers.find(u=>u.id===id&&u.active);if(!u)return;journey.user=id;state.role=u.space==='clinic'?'Profesional':u.role==='Comercial'?'Comercial':'Administrador';state.view='ruta';state.tab='Resumen';closeModal();render()}
function jGo(view,id){if(id)journey.patient=Number(id);state.view=view;closeModal();render();window.scrollTo(0,0)}
function jRoute(){const a=jAppointment(),p=jPatient(),bill=jBill(),stage=a?flowStep(a):-1,checks=[!!p,!!a,!!a&&a.status==='Confirmada'||stage>0,stage>=1,stage>=2,!!jNote(),stage>=3,!!bill,!!bill&&invoiceBalance(bill)===0,stage===4,careTasks.some(t=>t.visit===a?.id&&a)];const steps=[['Primer contacto','Recepción','Conserva el origen y convierte la conversación en una ficha.','Abrir WhatsApp','route-inbox'],['Reserva','Recepción','Define servicio, precio, duración y profesional.','Crear cita','route-book'],['Confirmación','Paciente','Simula la respuesta del paciente desde WhatsApp.','Ver confirmación','route-inbox'],['Llegada','Recepción','Registra la llegada para informar al equipo clínico.','Registrar llegada','route-arrive'],['Atención','Profesional','La profesional recibe al paciente e inicia la visita.','Iniciar atención','route-start'],['Registro clínico','Profesional','Odontograma, imágenes y evolución vinculados a la visita.','Abrir atención','route-clinical'],['Entrega al equipo','Profesional','Envía la visita a salida administrativa.','Entregar a administración','route-handoff'],['Cuenta de la visita','Administración','Revisa el valor acordado y genera la cuenta de prueba.','Crear cuenta demo','route-invoice'],['Pago','Administración','Registra un abono o el pago completo.','Registrar pago','route-payment'],['Salida','Administración','Cierra la visita, incluso con saldo pendiente registrado.','Completar salida','route-close'],['Seguimiento','Recepción','Asigna el acompañamiento y revisa el mensaje posterior.','Ver seguimiento','route-follow']];const count=checks.filter(Boolean).length;
return jShell('Una visita, de principio a fin.','Caso guiado · Sofía Restrepo · campaña Sonrisa consciente',`<section class="j-route-hero"><div><span class="eyebrow">CASO DE DEMOSTRACIÓN</span><h2>${journey.lead.name}</h2><p>Instagram · Reels · El Poblado</p><div class="j-inline"><span class="j-tag">${a?esc(a.status):'Consulta por WhatsApp'}</span><span>${a?fullDate(a.date)+' · '+a.time:'Sin cita asignada'}</span></div></div><div class="j-route-progress"><strong>${count}<small> / ${checks.length}</small></strong><span>hitos registrados</span><progress max="${checks.length}" value="${count}"></progress></div></section><div class="j-route-context"><span>Estás explorando: <b>${esc(userNow().name)} · ${userNow().role}</b></span><span>${a?esc(a.professional)+' · '+esc(a.site):'El profesional se asigna al reservar'}</span></div><div class="j-steps">${steps.map(([title,owner,desc,label,act],i)=>`<article class="j-step ${checks[i]?'done':''}"><span class="j-step-number">${checks[i]?'✓':String(i+1).padStart(2,'0')}</span><div><small>${owner}</small><h3>${title}</h3><p>${desc}</p>${jButton(checks[i]&&['route-arrive','route-start','route-handoff','route-close'].includes(act)?'Ver estado':label,act)}</div></article>`).join('')}</div><div class="j-two"><section class="surface padded"><h3>Lo que está conectado</h3><p>La misma cita actualiza la agenda, los mensajes, la atención y la cuenta. Cada paso muestra el perfil responsable.</p><div class="j-inline">${jButton('Abrir agenda','route-agenda')}${jButton('Reservas VIP','route-vip')}${jButton('Catálogo de servicios','goto','servicios')}</div></section><section class="surface padded"><h3>Actividad de la sesión</h3>${operationLog()}</section></div>`,jButton('Reiniciar demostración','reset'))}
function jConvert(){if(journey.lead.patient)return;const id=nextId(patients);patients.push({id,name:journey.lead.name,age:32,site:'El Tesoro',source:journey.lead.source,campaign:journey.lead.campaign,phone:journey.lead.phone,email:'sofia.demo@example.com',status:'Nueva',consent:true,created:'2026-10-02',last:'2026-10-02',nextAction:'Agendar valoración',attribution:{...campaignContext['Sonrisa consciente'],residence:'Medellín · El Poblado',evidence:'UTM de ejemplo',firstTouch:'2026-10-02'}});journey.lead.patient=id;journey.patient=id;logOperation('Sofía: ficha creada desde conversación con origen conservado');render();toast('Ficha creada. Continúa con Agendar valoración.')}
function jFill(text,a){const p=patient(a?.patient)||{name:journey.lead.name};const values={nombre:p.name.split(' ')[0],fecha:a?fullDate(a.date):'5 de octubre de 2026',hora:a?.time||'10:00',sede:a?.site||'El Tesoro',profesional:a?.professional||professionals[0]};return text.replace(/\{\{(\w+)\}\}/g,(m,k)=>values[k]??m)}
const jVersion=a=>[a.date,a.time,a.professional,a.site,a.type].join('|');
function jSendTemplate(a,event){const t=templates.find(t=>t.event===event&&t.enabled&&t.status.startsWith('Aprobada'));if(!t||!patient(a.patient).consent)return false;const version=jVersion(a);if(journey.messages.some(m=>m.appointment===a.id&&m.event===event&&m.version===version))return false;journey.messages.push({id:nextId(journey.messages),thread:jThread(a.patient),direction:'out',text:jFill(t.text,a),status:'Enviado · simulación',appointment:a.id,event,version});journey.automationLog.unshift({text:t.name+' · '+patient(a.patient).name,status:'Enviado en demo'});return true}
function jQueue(a){journey.automationLog.filter(x=>x.appointment===a.id&&x.status==='Programado').forEach(x=>x.status='Cancelado por cambio de cita');if(templates.some(t=>t.event==='24 horas antes'&&t.enabled))journey.automationLog.unshift({appointment:a.id,text:'Recordatorio · '+patient(a.patient).name+' · '+addDays(a.date,-1)+' '+a.time,status:'Programado'});jSendTemplate(a,'Reserva')}
function jInbox(){const ids=['lead',...new Set(journey.messages.map(m=>m.thread).filter(x=>x!=='lead')),'9'];const threads=[...new Set(ids)];const thread=journey.conversation,pid=thread==='lead'?journey.lead.patient:Number(thread),p=patient(pid),a=appointments.filter(a=>a.patient===pid&&a.status!=='Cancelada').sort((a,b)=>b.id-a.id)[0];const messages=journey.messages.filter(m=>m.thread===thread);return jShell('WhatsApp y confirmaciones','Bandeja compartida · conexión externa pendiente',`<div class="j-inbox"><aside class="surface j-threads"><h3>Conversaciones</h3>${threads.map(t=>jButton((t==='lead'?journey.lead.name:patient(Number(t))?.name||'Contacto')+'<small>'+(t==='lead'?'Instagram · Sonrisa consciente':'Paciente registrado')+'</small>','thread',t,thread===t?'active':'')).join('')}</aside><section class="surface j-conversation"><header><div><h2>${esc(p?.name||journey.lead.name)}</h2><p>${p?'Ficha vinculada · '+esc(p.phone):'Contacto nuevo · '+journey.lead.phone}</p></div><span class="j-tag">WhatsApp simulado</span></header><div class="j-message-list">${messages.map(m=>`<article class="j-message ${m.direction==='out'?'sent':''}"><p>${esc(m.text)}</p><small>${esc(m.status)}</small>${m.event==='Reserva'&&a&&m.appointment===a.id&&m.version===jVersion(a)&&['Reservada','Por confirmar'].includes(a.status)?`<div class="j-response"><span>Prueba la respuesta del paciente:</span>${jButton('Confirmar','reply-confirm',a.id)}${jButton('Solicitar cambio','reply-change',a.id)}${jButton('Cancelar cita','reply-cancel',a.id)}</div>`:''}</article>`).join('')||'<p class="quiet">Sin mensajes en esta conversación.</p>'}</div><form id="jMessageForm" class="j-composer"><label class="sr-only" for="jMessageText">Mensaje</label><input id="jMessageText" name="text" placeholder="Escribe una respuesta de prueba…" required maxlength="1500"><button class="btn primary" type="submit">Enviar en demo</button></form></section><aside class="surface padded"><span class="eyebrow">CONTEXTO DEL PACIENTE</span><h3>${esc(p?.source||journey.lead.source)}</h3><p>${esc(p?.campaign||journey.lead.campaign)}</p><p>${esc(p?.attribution?.placement||"Instagram · Reels")} · ${esc(p?.attribution?.zone||"Medellín · El Poblado")}<br><small>${esc(p?.attribution?.evidence||"UTM de ejemplo")}</small></p>${!p?jButton('Crear ficha del paciente','convert','','primary'):jButton('Agendar valoración','inbox-book',pid,'primary')}${a?`<hr><b>${esc(a.type)}</b><p>${fullDate(a.date)} · ${a.time}<br>${esc(a.professional)}<br>${esc(a.status)}</p>${jButton('Ver cita','appointment',a.id)}${jButton('Enviar confirmación demo','send-confirm',a.id)}`:''}<hr><label class="j-check"><input type="checkbox" data-j-consent="${pid||0}" ${p?.consent?'checked':''} ${!p?'disabled':''}> Autorización de contacto de ejemplo</label><p class="quiet">No se envían mensajes a números reales.</p></aside></div>`)}
function jComms(){const t=templates.find(t=>t.id===journey.selectedTemplate)||templates[0];return jShell('Plantillas y automatizaciones','Crea el mensaje, define el evento y prueba el resultado.',`<div class="j-two"><section class="surface padded"><div class="j-inline"><h2>Biblioteca de mensajes</h2>${jButton('Nueva plantilla','template-new','','primary')}</div>${templates.map(t=>`<div class="j-template"><div><b>${esc(t.name)}</b><small>${esc(t.event)} · ${esc(t.status)}</small></div><div class="j-inline">${jButton('Editar','template-edit',t.id)}${jButton(t.enabled?'Pausar':'Activar','template-toggle',t.id)}</div></div>`).join('')}<p class="quiet">Las aprobaciones se simulan. En producción dependen de WhatsApp.</p></section><section class="surface padded"><span class="eyebrow">VISTA PREVIA</span><h2>${esc(t.name)}</h2><div class="j-message sent"><p>${esc(jFill(t.text,jAppointment()))}</p><small>Vista previa · no enviado</small></div><p>Variables: {{nombre}}, {{fecha}}, {{hora}}, {{sede}}, {{profesional}}.</p>${jButton('Probar recordatorio de la cita','run-reminder','','primary')}<p class="quiet">La prueba ejecuta el evento de 24 horas antes de forma manual.</p></section></div><section class="surface padded j-section"><h2>Historial de automatizaciones</h2>${journey.automationLog.map(l=>`<div class="j-record"><span>${esc(l.text)}</span><b>${esc(l.status)}</b></div>`).join('')||'<p class="quiet">Reserva una cita para generar confirmación y recordatorio.</p>'}</section>`)}
function jTemplateForm(id){const t=templates.find(t=>t.id===Number(id));journey.selectedTemplate=t?.id||1;jModal(t?'Editar plantilla':'Nueva plantilla',`<input type="hidden" name="id" value="${t?.id||''}"><label>Nombre<input name="name" value="${esc(t?.name||'')}" required maxlength="100"></label><label>Evento<select name="event">${jOptions(['Reserva','24 horas antes','Salida completada'],t?.event)}</select></label><label>Texto<textarea name="text" rows="5" required maxlength="1200">${esc(t?.text||'Hola {{nombre}}, tu cita es el {{fecha}} a las {{hora}} con {{profesional}}.')}</textarea></label><p>Variables disponibles: {{nombre}}, {{fecha}}, {{hora}}, {{sede}}, {{profesional}}.</p>`,'template')}
function jServiceView(){return jShell('Servicios, valor y tiempo','Parámetros que alimentan la reserva. Valores ficticios en COP.',`<div class="j-service-grid">${services.map(s=>`<article class="surface padded"><span class="eyebrow">SERVICIO ${String(s.id).padStart(2,'0')}</span><h2>${esc(s.name)}</h2><div class="j-price">${fmt(s.price)}</div><p>${s.duration} min de atención + ${s.buffer} min de preparación<br>${s.sessions} sesión por reserva</p><p>${esc(s.professional)}</p>${jButton('Editar servicio','service-edit',s.id)}${jButton('Agendar','service-book',s.id,'primary')}</article>`).join('')}</div><p class="quiet">La cita conserva el precio y duración acordados al reservar. Cambiar el catálogo no modifica citas anteriores.</p>`,jButton('Nuevo servicio','service-new','','primary'))}
function jServiceForm(id){const s=services.find(s=>s.id===Number(id));jModal(s?'Editar servicio':'Nuevo servicio',`<input type="hidden" name="id" value="${s?.id||''}"><label>Nombre<input name="name" required maxlength="90" value="${esc(s?.name||'')}"></label><div class="form-grid"><label>Precio COP<input type="number" min="0" step="1000" name="price" required value="${s?.price||180000}"></label><label>Atención (min)<input type="number" min="15" max="240" step="15" name="duration" required value="${s?.duration||45}"></label><label>Preparación (min)<input type="number" min="0" max="60" step="15" name="buffer" required value="${s?.buffer??15}"></label><label>Profesional<select name="professional">${jOptions(professionals,s?.professional)}</select></label></div>`,'service')}
const jOldBooking=bookingForm;
bookingForm=function(opts={}){if(!canBook()){toast('Este perfil no gestiona reservas. Cambia a Recepción o Profesional.');return}jOldBooking(opts);const a=appointments.find(a=>a.id===opts.id),s=services.find(s=>s.id===(opts.service||a?.serviceId));$('#demoForm .form-grid').insertAdjacentHTML('afterbegin',`<label class="full">Servicio del catálogo<select id="jServiceSelect" name="serviceId"><option value="">Atención personalizada</option>${services.map(s=>`<option value="${s.id}" ${s.id===Number(opts.service||a?.serviceId)?'selected':''}>${esc(s.name)} · ${fmt(s.price)}</option>`).join('')}</select></label>`);$('#demoForm .form-grid').insertAdjacentHTML('beforeend',`<label>Valor acordado COP<input name="agreedPrice" type="number" min="0" step="1000" required value="${a?.agreedPrice??s?.price??180000}"></label><label>Preparación adicional (min)<input name="buffer" type="number" min="0" max="60" step="15" value="${a?.buffer??s?.buffer??0}" required></label><div class="full j-book-summary" id="jBookingSummary"></div>`);if(s)jApplyService(s);else{const dur=$('#demoForm [name=duration]');dur.innerHTML=[30,45,60,90,120].map(n=>`<option value="${n}" ${n===(a?.clinicalDuration||a?.duration||45)?'selected':''}>${n} minutos</option>`).join('');jBookingSummary()}};
function jApplyService(s){$('#demoForm [name=title]').value=s.name;$('#demoForm [name=professional]').value=s.professional;$('#demoForm [name=duration]').innerHTML=[...new Set([30,45,60,90,120,s.duration])].sort((a,b)=>a-b).map(n=>`<option value="${n}" ${n===s.duration?'selected':''}>${n} minutos</option>`).join('');$('#demoForm [name=agreedPrice]').value=s.price;$('#demoForm [name=buffer]').value=s.buffer;jBookingSummary()}
function jBookingSummary(){let f=$('#demoForm');if(!f?.elements.agreedPrice)return;$('#jBookingSummary').textContent=`Te atenderá ${f.elements.professional.value}. Se reservarán ${Number(f.elements.duration.value)+Number(f.elements.buffer.value)} minutos en la agenda · valor ${fmt(Number(f.elements.agreedPrice.value))}.`}
const jOldSave=saveForm;
saveForm=function(e){if(state.modal?.type!=='schedule')return jOldSave(e);e.preventDefault();if(!canBook())return;const d=Object.fromEntries(new FormData(e.target)),old=state.modal.editId;const a={patient:Number(d.patient),date:d.date,time:d.time,duration:Number(d.duration)+Number(d.buffer),clinicalDuration:Number(d.duration),buffer:Number(d.buffer),agreedPrice:Number(d.agreedPrice),serviceId:Number(d.serviceId)||null,type:d.title.trim(),site:d.site,professional:d.professional,status:'Reservada'};if(!a.type||!Number.isFinite(a.agreedPrice)||a.agreedPrice<0||!Number.isFinite(a.buffer)||a.buffer<0)return jFail('Revisa el valor y la duración.');const conflict=scheduleConflict(a,'appointment',old);if(conflict)return jFail(conflict);const patientConflict=appointments.find(x=>x.id!==old&&x.patient===a.patient&&x.status!=='Cancelada'&&overlap(x,a));if(patientConflict)return jFail('El paciente ya tiene otra cita en ese intervalo.');let saved;if(old){saved=appointments.find(x=>x.id===old);if(flowStep(saved)>0)return jFail('Solo puedes reprogramar una cita que no haya iniciado su recorrido.');Object.assign(saved,a)}else{saved={...a,id:nextId(appointments),treatment:null};appointments.push(saved)}jQueue(saved);state.agendaDay=state.calendarAnchor=saved.date;state.flowDate=saved.date;journey.patient=saved.patient;logOperation(`${patient(saved.patient).name}: cita ${old?'reprogramada':'reservada'} con ${saved.professional}`);closeModal();go('agenda');toast('Reserva actualizada. Confirmación simulada disponible en WhatsApp.')};
function jOdonto(){const p=patient(journey.patient)||patients[0],a=appointments.filter(a=>a.patient===p.id&&a.status!=='Cancelada').sort((a,b)=>b.id-a.id)[0],findings=journey.findings.filter(f=>f.patient===p.id),media=journey.media.filter(m=>m.patient===p.id);const rows=[[18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28],[48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38]];return jShell('Estudio clínico','Odontograma permanente, archivos y evolución de la visita.',`<div class="j-patient-picker"><label>Paciente<select id="jClinicalPatient">${patients.map(p=>`<option value="${p.id}" ${p.id===journey.patient?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div><b>${esc(p.name)}</b><p>${a?esc(a.professional)+' · '+fullDate(a.date):'Sin cita asignada'}</p></div>${jButton('Solicitar apoyo','support-new',p.id)}</div><div class="j-two j-clinical"><section class="surface padded"><div class="j-inline"><h2>Odontograma</h2><span class="j-tag">Dentición permanente · esquema 2D</span></div><p class="quiet">Selecciona una pieza y luego la superficie. Los colores representan el último registro de cada superficie.</p><div class="j-dental-scroll">${rows.map((row,i)=>`<div class="j-jaw-label">${i?'Arcada inferior':'Arcada superior'} · derecha del paciente a la izquierda de la pantalla</div><div class="j-jaw">${row.map(n=>{const fs=findings.filter(f=>f.tooth===n),latest=fs.at(-1);return `<button class="j-dental ${journey.tooth===n?'selected':''}" data-j="tooth" data-value="${n}" aria-label="Pieza ${n}${latest?' · '+esc(latest.condition):''}"><svg viewBox="0 0 50 50" aria-hidden="true">${[['Vestibular','M4 4H46L33 17H17Z'],['Lingual / palatina','M4 46H46L33 33H17Z'],['Mesial',n%10&&Math.floor(n/10)%2===1?'M46 4V46L33 33V17Z':'M4 4V46L17 33V17Z'],['Distal',Math.floor(n/10)%2===1?'M4 4V46L17 33V17Z':'M46 4V46L33 33V17Z'],['Oclusal / incisal','M17 17H33V33H17Z']].map(([surface,path])=>{const last=fs.filter(f=>f.surface===surface).at(-1);return `<path d="${path}" fill="${last?last.status==='Realizado'?'#23756c':last.status==='Planeado'?'#bf944f':'#c75c63':'#f0f5f5'}" stroke="#78969b" stroke-width="1"/>`}).join('')}</svg><b>${n}</b></button>`}).join('')}</div>`).join('')}</div><div class="j-legend"><span><i style="background:#c75c63"></i>Hallazgo</span><span><i style="background:#bf944f"></i>Planeado</span><span><i style="background:#23756c"></i>Realizado</span><span>Sin color: sin registro</span></div><div class="j-tooth-editor"><h3>Pieza ${journey.tooth}</h3><label>Superficie<select id="jSurface">${jOptions(['Oclusal / incisal','Mesial','Distal','Vestibular','Lingual / palatina'],journey.surface)}</select></label>${jButton('Registrar hallazgo / tratamiento','finding-new',p.id,'primary')}</div><h3>Historial de la pieza ${journey.tooth}</h3>${findings.filter(f=>f.tooth===journey.tooth).reverse().map(f=>`<div class="j-record"><div><b>${esc(f.condition)}</b><p>${esc(f.surface)} · ${esc(f.status)}</p><small>${esc(f.author)} · ${esc(f.date)}</small>${f.note?`<p>${esc(f.note)}</p>`:''}</div></div>`).join('')||'<p class="quiet">Sin registros. Cada guardado añade una entrada al historial.</p>'}</section><section class="surface padded"><span class="eyebrow">CONTINUIDAD CLÍNICA</span><h2>Evolución de la visita</h2><p>${a?esc(a.type)+' · '+esc(flowStages[flowStep(a)]):'Selecciona un paciente con cita para registrar su evolución.'}</p>${jButton('Registrar evolución','note-new',p.id,'primary')}<div class="j-note-list">${clinical.filter(c=>c.patient===p.id).slice().reverse().map(c=>`<article class="j-clinical-note"><b>${esc(c.type)} · ${dateLabel(c.date)}</b><p>${esc(c.text)}</p><small>${esc(c.professional)}</small></article>`).join('')||'<p class="quiet">Sin evoluciones registradas.</p>'}</div><h3>Coordinación</h3>${jButton('Abrir chat del paciente','chat-patient',p.id)}${a&&flowStep(a)===2?jButton('Entregar a administración','handoff',a.id):''}</section></div><section class="surface padded j-section"><div class="j-inline"><div><span class="eyebrow">ARCHIVO CLÍNICO</span><h2>Imágenes y documentos</h2></div>${jButton('Adjuntar archivo','media-new',p.id,'primary')}${jButton('Vista del paciente','patient-preview',p.id)}</div><p class="quiet">Archivos de prueba JPG, PNG, WebP o PDF, hasta 5 MB. Se conservan solo durante esta sesión. Usa material ficticio.</p><div class="j-gallery">${media.map(m=>`<article><div class="j-media-preview">${m.type.startsWith('image/')?`<img src="${m.url}" alt="${esc(m.label)}">`:'<div class="j-pdf">PDF</div>'}</div><h3>${esc(m.label)}</h3><p>${esc(m.category)} · ${m.tooth?'Pieza '+m.tooth:'General'}</p><small>${m.shared?'Visible en vista del paciente':'Solo equipo clínico'}</small><div class="j-inline">${jButton('Abrir','media-view',m.id)}${jButton(m.shared?'Ocultar al paciente':'Compartir en vista demo','media-share',m.id)}</div></article>`).join('')||'<div class="j-upload-empty"><b>El registro visual empieza aquí</b><p>Adjunta una imagen y clasifícala como Antes, Después o Radiografía para compararla en la ficha.</p></div>'}</div></section>`,jButton('Volver al flujo','goto','ruta'))}
function jFindingForm(id){if(!canClinical())return toast('El registro de hallazgos corresponde al perfil Profesional.');jModal('Registrar pieza '+journey.tooth,`<input type="hidden" name="patient" value="${id}"><input type="hidden" name="tooth" value="${journey.tooth}"><label>Superficie<select name="surface">${jOptions(['Oclusal / incisal','Mesial','Distal','Vestibular','Lingual / palatina'],journey.surface)}</select></label><label>Hallazgo o procedimiento<input name="condition" required maxlength="120" placeholder="Descripción del profesional"></label><label>Estado<select name="status">${jOptions(['Hallazgo','Planeado','Realizado'])}</select></label><label>Observaciones<textarea name="note" rows="3" maxlength="1200"></textarea></label><p>Se añadirá un registro firmado por el perfil de demostración. No sobrescribe entradas previas.</p>`,'finding')}
function jNoteForm(id){if(!canClinical())return toast('Cambia al perfil Profesional para registrar la evolución.');const a=appointments.filter(a=>a.patient===Number(id)&&a.status!=='Cancelada').sort((a,b)=>b.id-a.id)[0];if(!a||flowStep(a)!==2)return toast('Inicia la atención antes de registrar la evolución de esta visita.');jModal('Evolución clínica',`<input type="hidden" name="patient" value="${id}"><input type="hidden" name="visit" value="${a.id}"><div class="callout">${esc(patient(Number(id)).name)} · ${esc(a.professional)}</div><label>Registro del profesional<textarea name="text" rows="6" required maxlength="5000" placeholder="Registra la evolución de prueba…"></textarea></label><p>Registro de demostración. El chat interno se conserva por separado.</p>`,'note','Guardar evolución')}
function jMediaForm(id){if(!canClinical())return toast('Solo el perfil Profesional puede adjuntar archivos clínicos en esta demo.');jModal('Adjuntar archivo de prueba',`<input type="hidden" name="patient" value="${id}"><label>Nombre descriptivo<input name="label" required maxlength="100" placeholder="Fotografía frontal inicial"></label><label>Categoría<select name="category">${jOptions(['Antes','Después','Radiografía','Documento'])}</select></label><label>Pieza dental (opcional)<select name="tooth"><option value="">General</option>${[1,2,3,4].flatMap(q=>Array.from({length:8},(_,i)=>q*10+i+1)).map(n=>`<option>${n}</option>`).join('')}</select></label><label>Archivo<input type="file" name="file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label>`,'media','Adjuntar en demo')}
function jPatientPreview(id){const p=patient(id),a=appointments.filter(a=>a.patient===id&&a.status!=='Cancelada'&&flowStep(a)<4).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0],media=journey.media.filter(m=>m.patient===id&&m.shared);jModal('Vista del paciente · '+esc(p.name),`<p class="j-demo">Vista previa local. No se publica ni se envía un enlace.</p><div class="callout"><h3>${a?'Tu próxima atención':'Tu atención'}</h3><p>${a?fullDate(a.date)+' · '+a.time+' · '+esc(a.site):'Tu equipo coordinará la próxima visita.'}</p><b>${a?'Te atenderá '+esc(a.professional):'Gracias por visitarnos'}</b></div><h3>Archivos compartidos</h3><div class="j-gallery">${media.map(m=>`<article>${m.type.startsWith('image/')?`<img class="j-shared-image" src="${m.url}" alt="${esc(m.label)}">`:'<b>PDF</b>'}<p>${esc(m.category)} · ${esc(m.label)}</p>${jButton('Abrir','media-view',m.id)}</article>`).join('')||'<p>El profesional todavía no ha compartido archivos.</p>'}</div>`)}
function jTeam(){const pid=journey.patient||9,requests=journey.requests.filter(r=>r.patient===pid),messages=journey.chat.filter(m=>m.patient===pid);return jShell('Equipo y solicitudes de apoyo','Coordinación interna vinculada al paciente. Sin mensajes externos.',`<div class="j-patient-picker"><label>Paciente<select id="jChatPatient">${patients.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><b>${esc(patient(pid).name)}</b>${jButton('Solicitar apoyo','support-new',pid,'primary')}</div><div class="j-two"><section class="surface padded"><h2>Conversación interna</h2><div class="j-team-messages">${messages.map(m=>`<article class="j-clinical-note"><small>${esc(m.author)}</small><p>${esc(m.text)}</p></article>`).join('')||'<p class="quiet">Comparte una nota de coordinación con el equipo.</p>'}</div><form id="jChatForm" class="j-composer"><label class="sr-only" for="jChatText">Nota interna</label><input id="jChatText" name="text" required maxlength="1500" placeholder="Mensaje interno sobre esta visita…"><button class="btn primary">Enviar</button></form><p class="quiet">Los mensajes no se añaden a la historia clínica.</p></section><section class="surface padded"><h2>Solicitudes de apoyo</h2>${requests.map(r=>`<article class="j-request"><div class="j-inline"><b>${esc(r.reason)}</b><span class="j-tag">${esc(r.priority)}</span></div><p>Para ${esc(r.team)} · ${esc(r.location)}</p><small>Solicita ${esc(r.author)}</small><div class="j-inline"><span>${esc(r.status)}</span>${r.status==='Pendiente'?jButton('Aceptar solicitud','request-accept',r.id):r.status==='Aceptada'?jButton('Marcar resuelta','request-resolve',r.id):'<b>✓ Resuelta</b>'}</div>${r.owner?`<small>Responsable: ${esc(r.owner)}</small>`:''}</article>`).join('')||'<p class="quiet">No hay solicitudes para este paciente.</p>'}</section></div>`)}
function jSupportForm(id){const p=patient(Number(id))||patient(journey.patient)||patients[0];jModal('Solicitar apoyo',`<input type="hidden" name="patient" value="${p.id}"><div class="callout">${esc(p.name)}</div><label>Equipo<select name="team">${jOptions(['Auxiliar clínica','Recepción','Administración'])}</select></label><label>Motivo<input name="reason" required maxlength="140" placeholder="Preparar salida administrativa"></label><label>Ubicación<input name="location" required value="${esc(p.site)} · Consultorio 1" maxlength="100"></label><label>Prioridad<select name="priority">${jOptions(['Normal','Prioritaria'])}</select></label>`,'support','Crear solicitud')}
const roleScope={Recepción:['ruta','agenda','comunicaciones','mensajes','equipo','vip'],Profesional:['ruta','inicio','agenda','flujo','pacientes','clinico','estudio','vip','equipo'],Auxiliar:['ruta','equipo','vip'],Administrador:['ruta','inicio','agenda','salidas','finanzas','contabilidad','pacientes','crm','marketing','analitica','inventario','vip','comunicaciones','mensajes','equipo','servicios','usuarios','conexiones'],Contabilidad:['ruta','contabilidad','finanzas','equipo'],Comercial:['ruta','crm','marketing','comunicaciones','equipo']};
const jNavItems=[['ruta','Flujo completo','grid'],['comunicaciones','WhatsApp','heart'],['mensajes','Plantillas y reglas','brief'],['estudio','Odontograma e imágenes','heart'],['equipo','Chat y apoyo interno','users'],['servicios','Servicios y tarifas','brief'],['usuarios','Usuarios y roles','users'],['conexiones','Conexiones y dominio','brief']];
function jUsers(){return jShell('Usuarios y roles','Explora las responsabilidades. Las cuentas y permisos reales requieren backend.',`<div class="surface table-wrap"><table class="data-table"><thead><tr><th>Persona</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${demoUsers.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.role)}</td><td>${u.active?'Activo':'Suspendido'} · demo</td><td>${jButton('Editar rol','user-edit',u.id)}${jButton(u.active?'Suspender':'Activar','user-toggle',u.id)}${u.active?jButton('Explorar perfil','user-switch',u.id):''}</td></tr>`).join('')}</tbody></table></div><section class="surface padded j-section"><h2>Matriz de acceso de demostración</h2><div class="j-permissions">${Object.entries(roleScope).map(([r,vs])=>`<article><h3>${r}</h3><p>${vs.filter(x=>x!=='ruta').map(x=>[...jNavItems,...clinicNav,...businessNav].find(i=>i[0]===x)?.[1]||x).join(' · ')}</p></article>`).join('')}</div><p class="quiet">Cambiar el perfil modifica la navegación de esta sesión. No es autenticación ni autorización de servidor.</p></section>`,jButton('Crear usuario demo','user-new','','primary'))}
function jUserForm(id){const u=demoUsers.find(u=>u.id===id);jModal(u?'Editar usuario':'Crear usuario demo',`<input type="hidden" name="id" value="${esc(u?.id||'')}"><label>Nombre<input name="name" required maxlength="100" value="${esc(u?.name||'')}"></label><label>Rol<select name="role">${jOptions(Object.keys(roleScope),u?.role||'Recepción')}</select></label><p>No se crean credenciales ni se envían invitaciones.</p>`,'user')}
function jConnections(){return jShell('Conexiones y dominio','Configuración de referencia para preparar la puesta en marcha.',`<div class="j-two"><section class="surface padded"><span class="j-tag">Sin conexión</span><h2>WhatsApp Business</h2><p>Canal previsto: ${esc(journey.integrations.channel)}</p><ol><li>Vincular cuenta empresarial y número.</li><li>Configurar API y recepción de respuestas.</li><li>Enviar plantillas a aprobación.</li><li>Probar confirmaciones con un número autorizado.</li></ol><p class="quiet">La bandeja actual usa datos simulados. No se solicitan claves en este prototipo.</p>${jButton('Editar configuración de referencia','connection-form','','primary')}</section><section class="surface padded"><span class="j-tag">Pendiente de configurar</span><h2>Dominio y alojamiento</h2><p><b>${esc(journey.integrations.domain||'Dominio por definir')}</b></p><p>${esc(journey.integrations.hosting)}</p><p>Aplicación · base de datos · archivos privados · respaldos · monitorización.</p><p class="quiet">Guardar aquí no compra un dominio, no provisiona un VPS ni modifica DNS.</p></section></div>`)}
function jConnectionForm(){jModal('Plan de conexión',`<label>API de WhatsApp<select name="channel">${jOptions(['Meta Cloud API','Proveedor oficial'],journey.integrations.channel)}</select></label><label>Dominio previsto<input name="domain" value="${esc(journey.integrations.domain)}" placeholder="app.miclinica.com" maxlength="180"></label><label>Alojamiento previsto<select name="hosting">${jOptions(['Servicios administrados','VPS administrado'],journey.integrations.hosting)}</select></label><p>Datos de planificación. Sin conexión externa.</p>`,'connection','Guardar referencia')}
function jPaymentForm(a){const bill=invoices.find(i=>i.visit===a.id);if(!bill)return toast('Primero crea la cuenta de la visita.');const balance=invoiceBalance(bill);if(balance<=0)return toast('La cuenta ya está pagada.');jModal('Registrar pago de prueba',`<input type="hidden" name="invoice" value="${bill.id}"><div class="callout">${esc(patient(a.patient).name)}<br>Cuenta ${esc(bill.number)} · saldo ${fmt(balance)}</div><label>Abono COP<input name="amount" type="number" min="1" max="${balance}" value="${balance}" required></label><label>Medio<select name="method">${jOptions(['Transferencia demo','Tarjeta demo','Efectivo demo'])}</select></label><p>Registro simulado; no se procesa ningún cobro real.</p>`,'payment','Registrar abono')}
function jMakeBill(a){if(!a||flowStep(a)<3)return toast('La atención debe entregarse a administración.');if(invoices.some(i=>i.visit===a.id))return toast('La cuenta ya existe. Puedes registrar el pago.');const amount=a.agreedPrice??180000;state.period=a.date.slice(0,7);invoices.push({id:nextId(invoices),patient:a.patient,treatment:a.treatment,date:a.date,amount,number:'CUENTA-DEMO-'+a.id,visit:a.id});logOperation('Cuenta demo de '+patient(a.patient).name+' por '+fmt(amount));render();toast('Cuenta de prueba creada. Visible en Facturación y cartera.')}
function jFollow(a){if(!careTasks.some(t=>t.visit===a.id)){careTasks.push({id:nextId(careTasks),patient:a.patient,visit:a.id,title:'Confirmar recepción de indicaciones y resolver dudas',date:addDays(a.date,1),owner:'Laura Martínez',done:false})}jSendTemplate(a,'Salida completada')}
const jOldAdvance=advanceFlow;
advanceFlow=function(id,close=false){const a=appointments.find(a=>a.id===id);if(!a)return;if(close){if(!canFinance())return toast('La salida corresponde a Administración.')}else if(flowStep(a)===0){if(!canBook())return toast('La llegada corresponde a Recepción.');visitFlow[id]=1;logOperation(patient(a.patient).name+': llegada registrada');render();return}else if(!canClinical())return toast('Este paso corresponde al perfil Profesional.');if(!close&&flowStep(a)===2&&!clinical.some(c=>c.visit===id))return toast('Registra la evolución de la visita antes de entregarla.');jOldAdvance(id,close);if(close&&flowStep(a)===4){jFollow(a);render()}};
function jRouteAction(action){const a=jAppointment(),p=jPatient();if(action==='route-inbox'){jSwitch('reception');journey.conversation='lead';return jGo('comunicaciones')}if(action==='route-book'){if(!p)return toast('Primero crea la ficha desde WhatsApp.');jSwitch('reception');state.patient=p.id;state.agendaDay='2026-10-05';return bookingForm({date:'2026-10-05',time:'10:00',service:1})}if(action==='route-clinical'){if(!a||flowStep(a)<2)return toast('Primero registra llegada e inicia atención.');jSwitch('dentist');return jGo('estudio',p.id)}if(action==='route-agenda'){jSwitch('reception');if(a)state.agendaDay=state.calendarAnchor=a.date;return jGo('agenda')}if(action==='route-vip'){jSwitch('reception');jGo('agenda');return vipForm()}if(!a)return toast('Primero reserva la cita del paciente.');if(action==='route-arrive'){if(flowStep(a)>0)return toast('La llegada ya está registrada.');if(a.status!=='Confirmada')return toast('Confirma primero la cita en WhatsApp.');jSwitch('reception');advanceFlow(a.id);return}if(action==='route-start'){if(flowStep(a)!==1)return toast(flowStep(a)>1?'La atención ya fue iniciada.':'Registra primero la llegada.');jSwitch('dentist');advanceFlow(a.id);return}if(action==='route-handoff'){if(flowStep(a)!==2)return toast('El paciente debe estar en atención.');jSwitch('dentist');advanceFlow(a.id);return}if(action==='route-invoice'){jSwitch('admin');jMakeBill(a);return}if(action==='route-payment'){jSwitch('admin');return jPaymentForm(a)}if(action==='route-close'){if(flowStep(a)!==3)return toast('La visita debe estar en salida administrativa.');if(!jBill())return toast('Crea primero la cuenta de la visita.');jSwitch('admin');advanceFlow(a.id,true);return}if(action==='route-follow'){if(flowStep(a)!==4)return toast('Completa primero la salida para programar el seguimiento.');jSwitch('reception');journey.patient=p.id;jGo('vip');return}}
function jAction(action,value){const n=Number(value);if(action.startsWith('route-'))return jRouteAction(action);if(action==='close')return closeModal();if(action==='goto'){if(value==='servicios'&&!roleScope[userNow().role].includes(value))jSwitch('admin');return jGo(value);}if(action==='reset')return jModal('Reiniciar demostración',`<p>Se perderán las citas, mensajes, archivos y cambios creados en esta sesión.</p>${jButton('Reiniciar ahora','reset-confirm','','primary')}`);if(action==='reset-confirm')return location.reload();if(action==='thread'){journey.conversation=value;return render()}if(action==='convert')return jConvert();if(action==='inbox-book'){state.patient=n;state.agendaDay='2026-10-05';return bookingForm({date:'2026-10-05',time:'10:00',service:1})}if(action==='appointment')return detailDialog(appointments.find(a=>a.id===n));if(action==='send-confirm'){const a=appointments.find(a=>a.id===n);if(a.status==='Cancelada'||flowStep(a)>0)return toast('La cita no admite confirmación.');const sent=jSendTemplate(a,'Reserva');render();return toast(sent?'Confirmación enviada en la simulación.':'Ya enviada, plantilla pausada o sin autorización de contacto.')}if(action.startsWith('reply-')){const a=appointments.find(a=>a.id===n);if(!a||a.status==='Cancelada'||flowStep(a)>0)return toast('Esta cita ya no admite esa respuesta.');let text;if(action==='reply-confirm'){a.status='Confirmada';text='Confirmo mi cita, gracias.'}else if(action==='reply-change'){a.changeRequested=true;text='Necesito cambiar el horario. ¿Me ayudan?';journey.requests.push({id:nextId(journey.requests),patient:a.patient,reason:'Solicitud de cambio de cita',team:'Recepción',location:a.site,priority:'Normal',status:'Pendiente',author:patient(a.patient).name})}else{a.status='Cancelada';text='Deseo cancelar la cita.';jCancelMessages(a)}journey.messages.push({id:nextId(journey.messages),thread:jThread(a.patient),direction:'in',text,status:'Respuesta simulada'});logOperation(patient(a.patient).name+': '+text);render();return}if(action==='template-new')return jTemplateForm();if(action==='template-edit')return jTemplateForm(n);if(action==='template-toggle'){const t=templates.find(t=>t.id===n);t.enabled=!t.enabled;if(t.enabled)templates.filter(x=>x.id!==t.id&&x.event===t.event).forEach(x=>x.enabled=false);if(!t.enabled)journey.automationLog.filter(l=>l.status==='Programado'&&t.event==='24 horas antes').forEach(l=>l.status='Pausado');return render()}if(action==='run-reminder'){const a=jAppointment();if(!a||a.status==='Cancelada'||flowStep(a)>0)return toast('Reserva una cita pendiente para probar su recordatorio.');if(!jSendTemplate(a,'24 horas antes'))return toast('Ya ejecutado, plantilla pausada o sin autorización.');journey.automationLog.filter(l=>l.appointment===a.id&&l.status==='Programado').forEach(l=>l.status='Ejecutado en demo');render();return toast('Recordatorio de prueba visible en WhatsApp.')}if(action==='service-new')return jServiceForm();if(action==='service-edit')return jServiceForm(n);if(action==='service-book'){if(!canBook())return toast('Explora Recepción para agendar.');return bookingForm({service:n})}if(action==='tooth'){journey.tooth=n;return render()}if(action==='finding-new')return jFindingForm(n);if(action==='note-new')return jNoteForm(n);if(action==='media-new')return jMediaForm(n);if(action==='media-share'){if(!canClinical())return;const m=journey.media.find(m=>m.id===n);m.shared=!m.shared;return render()}if(action==='media-view'){const m=journey.media.find(m=>m.id===n);jModal(esc(m.label),m.type.startsWith('image/')?`<img class="j-full-image" src="${m.url}" alt="${esc(m.label)}">`:`<a class="btn primary" href="${m.url}" target="_blank" rel="noopener">Abrir PDF de prueba</a>`);return}if(action==='patient-preview')return jPatientPreview(n);if(action==='chat-patient')return jGo('equipo',n);if(action==='support-new')return jSupportForm(n||journey.patient);if(action==='request-accept'||action==='request-resolve'){const r=journey.requests.find(r=>r.id===n);const role=userNow().role,allowed=r.team==='Auxiliar clínica'?['Auxiliar','Profesional']:r.team==='Recepción'?['Recepción']:['Administrador'];if(!allowed.includes(role)&&role!=='Administrador')return toast('Explora el perfil del equipo destinatario para gestionar esta solicitud.');r.status=action==='request-accept'?'Aceptada':'Resuelta';r.owner=userNow().name;logOperation(r.reason+': '+r.status+' por '+r.owner);return render()}if(action==='handoff'){advanceFlow(n);return}if(action==='user-new')return jUserForm();if(action==='user-edit')return jUserForm(value);if(action==='user-switch')return jSwitch(value);if(action==='user-toggle'){const u=demoUsers.find(u=>u.id===value);if(u.id===journey.user)return toast('No puedes suspender el perfil activo.');u.active=!u.active;return render()}if(action==='connection-form')return jConnectionForm();}
periodControls=function(){const months=[...new Set(['2026-08','2026-09','2026-10',...invoices.map(i=>monthOf(i.date)),...payments.map(p=>monthOf(p.date))])].sort().reverse();return `<div class="range-controls"><select id="periodSelect" aria-label="Periodo">${months.map(m=>`<option value="${m}" ${m===state.period?'selected':''}>${new Date(m+'-01T12:00:00').toLocaleDateString('es-CO',{month:'long',year:'numeric'})}</option>`).join('')}</select></div>`};
function jCancelMessages(a){journey.automationLog.filter(l=>l.appointment===a.id&&['Programado','Pausado'].includes(l.status)).forEach(l=>l.status='Cancelado por cambio de cita')}
async function jSave(e){e.preventDefault();const kind=state.modal?.kind,d=Object.fromEntries(new FormData(e.target));if(kind==='template'){const unknown=[...d.text.matchAll(/\{\{(\w+)\}\}/g)].map(m=>m[1]).filter(k=>!['nombre','fecha','hora','sede','profesional'].includes(k));if(unknown.length)return jFail('Variable no reconocida: '+unknown.join(', '));let t=templates.find(t=>t.id===Number(d.id));/* only one active rule per event */if(!t){t={id:nextId(templates),enabled:false,status:'Borrador · simulación'};templates.push(t)}Object.assign(t,{name:d.name.trim(),event:d.event,text:d.text.trim(),status:'Aprobada · simulación'});templates.filter(x=>x.id!==t.id&&x.event===t.event).forEach(x=>x.enabled=false);t.enabled=true;journey.selectedTemplate=t.id}
else if(kind==='service'){if(userNow().role!=='Administrador')return jFail('La edición del catálogo corresponde a Administración.');const record={name:d.name.trim(),price:Number(d.price),duration:Number(d.duration),buffer:Number(d.buffer),professional:d.professional,sessions:1};if(!record.name||record.duration<15||record.price<0)return jFail('Revisa los datos del servicio.');const s=services.find(s=>s.id===Number(d.id));if(s)Object.assign(s,record);else services.push({...record,id:nextId(services)})}
else if(kind==='finding'){if(!canClinical())return;journey.findings.push({id:nextId(journey.findings),patient:Number(d.patient),tooth:Number(d.tooth),surface:d.surface,condition:d.condition.trim(),status:d.status,note:d.note.trim(),date:new Date().toLocaleString('es-CO'),author:userNow().name});logOperation('Registro en odontograma · '+patient(Number(d.patient)).name+' · pieza '+d.tooth)}
else if(kind==='note'){if(!canClinical())return;const a=appointments.find(a=>a.id===Number(d.visit));if(flowStep(a)!==2)return jFail('La visita ya no está en atención.');clinical.push({id:nextId(clinical),patient:Number(d.patient),visit:a.id,date:a.date,professional:a.professional,type:'Evolución',text:d.text.trim()});logOperation('Evolución registrada para '+patient(Number(d.patient)).name)}
else if(kind==='media'){if(!canClinical())return;const file=e.target.elements.file.files[0];if(!file||file.size>5*1024*1024||!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type))return jFail('Selecciona JPG, PNG, WebP o PDF de máximo 5 MB.');journey.media.push({id:nextId(journey.media),patient:Number(d.patient),label:d.label.trim(),category:d.category,tooth:Number(d.tooth)||null,type:file.type,url:URL.createObjectURL(file),shared:false})}
else if(kind==='support'){journey.requests.push({id:nextId(journey.requests),patient:Number(d.patient),team:d.team,reason:d.reason.trim(),priority:d.priority,location:d.location.trim(),status:'Pendiente',author:userNow().name});journey.patient=Number(d.patient);state.view='equipo';logOperation('Apoyo solicitado para '+patient(journey.patient).name)}
else if(kind==='user'){if(userNow().role!=='Administrador')return;const u=demoUsers.find(u=>u.id===d.id);if(u?.id===journey.user&&d.role!=='Administrador')return jFail('Conserva el rol del administrador activo.');const rec={name:d.name.trim(),role:d.role,space:['Profesional','Auxiliar'].includes(d.role)?'clinic':'business'};if(u)Object.assign(u,rec);else demoUsers.push({...rec,id:'u'+Date.now(),active:true})}
else if(kind==='connection')journey.integrations={...d};
else if(kind==='payment'){if(!canFinance())return;const bill=invoices.find(i=>i.id===Number(d.invoice)),amount=Number(d.amount);if(!bill||!Number.isFinite(amount)||amount<=0||amount>invoiceBalance(bill))return jFail('El abono debe ser mayor que cero y no superar el saldo.');payments.push({id:nextId(payments),patient:bill.patient,invoice:bill.id,date:bill.date,amount,method:d.method});logOperation('Pago demo de '+fmt(amount)+' · '+patient(bill.patient).name)}closeModal();render();toast('Guardado en esta sesión de demostración.')}
Object.assign(views,{ruta:jRoute,comunicaciones:jInbox,mensajes:jComms,estudio:jOdonto,equipo:jTeam,servicios:jServiceView,usuarios:jUsers,conexiones:jConnections});
const jOldClinicalTab=clinicalTab;
clinicalTab=function(p){return `<div class="j-inline">${jButton('Abrir odontograma e imágenes','clinical-patient',p.id,'primary')}${jButton('Solicitar apoyo','support-new',p.id)}</div>`+jOldClinicalTab(p)};
const jBaseDetail=detailDialog;
detailDialog=function(a){jBaseDetail(a);$('#modalRoot .callout').insertAdjacentHTML('beforeend',`<p>Atención: ${a.clinicalDuration||a.duration} min${a.buffer?' + '+a.buffer+' min de preparación':''}${a.agreedPrice!=null?' · '+fmt(a.agreedPrice):''}</p>`);$('#modalRoot .modal-actions').insertAdjacentHTML('afterbegin',jButton('Vista del paciente','patient-preview',a.patient));if(flowStep(a)>0)$('#modalRoot [data-schedule-edit]')?.remove()};
render=function(){let all=[...jNavItems,...clinicNav,...businessNav],seen=new Set(),scope=roleScope[userNow().role]||roleScope.Recepción;const navItems=all.filter(([key])=>{if(seen.has(key)||!scope.includes(key))return false;seen.add(key);return true});if(!scope.includes(state.view)&&state.view!=='detalle')state.view='ruta';if(state.view==='detalle'&&!scope.includes('pacientes'))state.view='ruta';$('#nav').innerHTML=`<div class="j-profile"><small>EXPLORAR PERFIL · DEMO</small><label class="sr-only" for="jUserSelect">Perfil de demostración</label><select id="jUserSelect">${demoUsers.filter(u=>u.active).map(u=>`<option value="${u.id}" ${u.id===journey.user?'selected':''}>${esc(u.name)} · ${u.role}</option>`).join('')}</select></div><div class="nav-section">${userNow().space==='clinic'?'ATENCIÓN Y COORDINACIÓN':'OPERACIÓN Y GESTIÓN'}</div>`+navItems.map(([key,label,i])=>`<button class="nav-btn ${state.view===key?'active':''}" data-nav="${key}">${icon(i)}<span>${label}</span></button>`).join('')+`<div class="workspace-disclaimer">Demo de perfiles · sin cuentas reales<br>Datos en esta sesión del navegador.</div>`;$('#crumbTitle').textContent=navItems.find(x=>x[0]===state.view)?.[1]||'Paciente';$('#content').innerHTML=(views[state.view]||jRoute)();$('#sidebar').classList.remove('open');$('#siteSelect').value=state.site;$('#roleSelect').value=state.role;$('#globalSearch').value=state.query;document.body.dataset.space=userNow().space;};
switchSpace=function(space){jSwitch(space==='clinic'?'dentist':'admin')};
// Capture only new controls and legacy actions whose role or reminder lifecycle changes.
document.addEventListener('click',e=>{const b=e.target.closest('[data-j]');if(b){e.preventDefault();e.stopImmediatePropagation();if(b.dataset.j==='clinical-patient'){if(!canClinical())return toast('Explora el perfil Profesional.');return jGo('estudio',Number(b.dataset.value))}jAction(b.dataset.j,b.dataset.value);return}const cancel=e.target.closest('[data-schedule-cancel]');if(cancel){const a=appointments.find(a=>a.id===Number(cancel.dataset.scheduleCancel));if(flowStep(a)>0){e.preventDefault();e.stopImmediatePropagation();return toast('Una visita iniciada debe cerrarse desde su recorrido.')}jCancelMessages(a)}const needsFinance=e.target.closest('[data-business-patient],[data-flow-close],[data-reconcile],[data-export-ledger],[data-approve]');if(needsFinance&&!canFinance()){e.preventDefault();e.stopImmediatePropagation();return toast('Esta acción corresponde a Administración o Contabilidad.')}const booking=e.target.closest('[data-vip-new],[data-vip-toggle],[data-slot-book],[data-slot-vip],[data-schedule-edit],[data-schedule-cancel],[data-schedule-confirm],[data-confirm]');if(booking&&!canBook()){e.preventDefault();e.stopImmediatePropagation();toast('Este perfil no gestiona la agenda.')}},true);
document.addEventListener('submit',e=>{if(e.target.id==='journeyForm'){e.stopImmediatePropagation();jSave(e)}if(e.target.id==='jMessageForm'){e.preventDefault();let text=e.target.elements.text.value.trim();if(!text)return;journey.messages.push({id:nextId(journey.messages),thread:journey.conversation,direction:'out',text,status:'Enviado · simulación'});render()}if(e.target.id==='jChatForm'){e.preventDefault();const text=e.target.elements.text.value.trim();if(!text)return;journey.chat.push({id:nextId(journey.chat),patient:journey.patient,author:userNow().name+' · '+userNow().role,text});render()}},true);
document.addEventListener('change',e=>{const el=e.target;if(el.id==='jUserSelect')jSwitch(el.value);if(el.id==='jClinicalPatient'||el.id==='jChatPatient'){journey.patient=Number(el.value);render()}if(el.id==='jSurface')journey.surface=el.value;if(el.id==='jServiceSelect'){const s=services.find(s=>s.id===Number(el.value));if(s)jApplyService(s)}if(el.closest('#demoForm')&&state.modal?.type==='schedule')jBookingSummary();if(el.hasAttribute('data-j-consent')){const p=patient(Number(el.dataset.jConsent));if(p)p.consent=el.checked}},true);
const oldNotify=$('#notifyBtn'),newNotify=oldNotify.cloneNode(true);oldNotify.replaceWith(newNotify);newNotify.setAttribute('aria-label','Solicitar apoyo interno');newNotify.setAttribute('title','Solicitar apoyo interno');newNotify.addEventListener('click',()=>jSupportForm(journey.patient));$('#roleSelect').style.display='none';
journey.messages.push({id:2,thread:'9',direction:'in',text:'Hola, quisiera confirmar quién me atenderá en el control.',status:'Recibido · demo'});
